(async () => { const l = (await lc.sessionState()).live;
      if (!l || l.state !== 'on') throw Error('the AI session did not start: ' + (l ? l.state + (l.reason ? ' (' + l.reason + ')' : '') : 'none'));
      const span = Date.parse(l.expires_at) - Date.parse(l.since);
      if (l.max_submissions !== 4 || l.min_observation_interval_ms !== 60000 || Math.abs(span - 60000) > 2000) throw Error('the session policy is not 4 / 1 min / 60 s');
      return JSON.stringify({ id: l.id, model: l.model, since: l.since, expires_at: l.expires_at, span_ms: span, max_submissions: l.max_submissions, reserve: l.reserve, min_observation_interval_ms: l.min_observation_interval_ms, used: l.used, out: l.out }); })()

(async () => { const l = (await lc.sessionState()).live;
  if (!l || l.state !== 'on') throw Error('the AI session is no longer on (' + (l ? l.state + (l.ended ? ': ' + l.ended : '') : 'none') + '): the remaining actions stay NOT_RUN');
  if (l.out !== 0) throw Error('a request is still out');
  if (l.used !== 1) throw Error('the session counted ' + l.used + ' request(s), not 1: the run stops (no retry)');
  if (l.seen === null) throw Error('no look was completed: ' + (l.missed ?? 'unknown'));
  return JSON.stringify({ used: l.used, out: l.out, max_submissions: l.max_submissions, reserve: l.reserve, expires_at: l.expires_at, seen: l.seen, missed: l.missed, paused: l.paused, frames: l.frames, unwritten: l.unwritten, at: new Date().toISOString() }); })()

